class BudgetedLayerBandit(LayerBanditSampler):
    def __init__(self, num_layers, K=256, eta_w=0.3, **kw):
        super().__init__(num_layers, **kw)
        self.K, self.eta_w = K, eta_w
        self.w = np.ones(num_layers)
    def sample_neighbors(self, node_ids, layer):
        k_l = int(self.K * self.w[layer] / self.w.sum())
        k_l = max(k_l,1)
        idx, p = super().sample_neighbors(node_ids, layer, k_l)
        return idx, p
    def update_budget(self, layer_variances):
        V_bar = np.mean(layer_variances)
        self.w *= np.exp(self.eta_w * layer_variances / (V_bar+1e-8))
    # call after each minibatch
    def end_of_batch(self, var_per_layer):
        self.update_budget(var_per_layer)

class HypeBabs(LayerBanditSampler):
    def __init__(self, layers, K0=128, classes=(1,2,4,8,16),   alpha=0.5, beta=0.02):
        super().__init__(layers)
        self.K, self.Kmin = K0, max(16,int(0.1*K0))
        self.classes = np.array(classes)
        self.alpha, self.beta = alpha, beta
        # per-layer contextual bandits: simple LinUCB with 3-d context
        self.ctxB = [LinUCB(len(classes), ctx_dim=3) for _ in range(layers)]
        self.cost = self._bench_device()
    def _bench_device(self):
        # micro-benchmark: measure ms for dummy matmul at each budget
        cost = {}
        for c in self.classes:
            start=time.perf_counter(); dummy=torch.randn(c,32).cuda()*0.0; torch.cuda.synchronize(); cost[c]=time.perf_counter()-start
        return cost
    def sample(self, v, layer, deg, grad_norm, last_loss):
        ctx = np.array([deg, grad_norm, last_loss])
        b_idx = self.ctxB[layer].select(ctx) # returns index in classes
        k = int(self.classes[b_idx])
        idx, p = super().sample_neighbors(v, layer, k)
        return idx, p, b_idx, ctx
    def end_of_batch(self, rewards):
        # rewards: list[(layer, b_idx, ctx, r_node)]
        for ℓ,b,ctx,r in rewards:
            self.ctxB[ℓ].update(b, ctx, r)
        # anneal global K
        self.K = max(self.Kmin, int(self.K*(1-self.beta*(1-self.var_ratio()))))
    def var_ratio(self):
        # returns σ²_t / σ²_0 approximation
        return np.clip(self.current_var / self.init_var,0,1)
